    "<div class=\"empty\">没有发出去：{0}</div>": "<div class=\"empty\">전송하지 못했습니다: {0}</div>",
    "<div class=\"empty\">没有开起来：{0}</div>": "<div class=\"empty\">열리지 않았습니다: {0}</div>",
    "<div class=\"empty\">没读到：{0}</div>": "<div class=\"empty\">읽지 못했습니다: {0}</div>",
    "<div class=\"empty\">没走：{0}</div>": "<div class=\"empty\">거치지 않음: {0}</div>",
    "<div class=\"empty\">没跑起来：{0}</div>": "<div class=\"empty\">실행되지 않았습니다: {0}</div>",
    "<div class=\"empty\">没量成：{0}</div>": "<div class=\"empty\">측정하지 못했습니다: {0}</div>",
    "<div class=\"empty\">测不了：{0}</div>": "<div class=\"empty\">측정할 수 없습니다: {0}</div>",
